const triggerData = $('Receive Meeting Context').first().json;
const notionItems = $input.all();

let projectId = null;
let projectName = 'New expansion';
let existingNotes = '';

if (notionItems && notionItems.length > 0) {
  const first = notionItems[0].json;
  projectId = first.id || null;
  projectName = first.name || 'New expansion';
  existingNotes = (first.properties && first.properties.Notes && first.properties.Notes.rich_text && first.properties.Notes.rich_text[0] && first.properties.Notes.rich_text[0].plain_text) || '';
}

// Use newly created Slack channel ID if one was auto-created this execution
let slackChannelId;
try {
  slackChannelId = $('Create Company Channel').first().json.id;
} catch(e) {
  slackChannelId = triggerData.slackChannelId || '';
}

return [{
  json: {
    projectId,
    projectName,
    existingNotes,
    meetingId: triggerData.meetingId,
    meetingTitle: triggerData.meetingTitle,
    meetingDate: triggerData.meetingDate,
    transcriptUrl: triggerData.transcriptUrl,
    lastCallSummary: triggerData.lastCallSummary,
    actionItems: triggerData.actionItems,
    gist: triggerData.gist,
    contactId: triggerData.contactId,
    contactName: triggerData.contactName,
    contactEmail: triggerData.contactEmail,
    contactRole: triggerData.contactRole,
    companyId: triggerData.companyId,
    companyName: triggerData.companyName,
    companyIndustry: triggerData.companyIndustry,
    slackChannelId,
    dealId: triggerData.dealId,
    dealName: triggerData.dealName,
    dealStage: triggerData.dealStage
  }
}];

