const claudeOutput = $input.first().json;
const projectData = $('Extract Project Info').first().json;

// Extract text from Claude response
let rawText = '';
if (claudeOutput.content && Array.isArray(claudeOutput.content)) {
  rawText = claudeOutput.content.map(c => c.text || '').join('');
} else if (claudeOutput.text) {
  rawText = claudeOutput.text;
} else if (typeof claudeOutput === 'string') {
  rawText = claudeOutput;
}

// Parse JSON - strip code fences if present
const jsonMatch = rawText.match(/```(?:json)?\n?([\s\S]*?)```/) || rawText.match(/(\{[\s\S]*\})/);
const jsonStr = jsonMatch ? jsonMatch[1] : rawText;
let addendum = {};
try {
  addendum = JSON.parse(jsonStr.trim());
} catch(e) {
  addendum = {
    addendumTitle: 'Expansion Addendum',
    executiveSummary: rawText,
    expansionScope: '',
    additionalDeliverables: [],
    proposedTimeline: 'TBD',
    commercialNote: '',
    nextSteps: 'Review and sign'
  };
}

const deliverablesText = Array.isArray(addendum.additionalDeliverables)
  ? addendum.additionalDeliverables.map((d, i) => (i + 1) + '. ' + d).join('\n')
  : '';

const docContent = 'EXPANSION ADDENDUM\n\n' +
  'Client: ' + projectData.companyName + '\n' +
  'Project: ' + projectData.projectName + '\n' +
  'Addendum: ' + (addendum.addendumTitle || '') + '\n' +
  'Prepared by: Novagentica\n' +
  'Date: ' + projectData.meetingDate + '\n\n' +
  'EXECUTIVE SUMMARY\n' +
  (addendum.executiveSummary || '') + '\n\n' +
  'ADDITIONAL SCOPE\n' +
  (addendum.expansionScope || '') + '\n\n' +
  'ADDITIONAL DELIVERABLES\n' +
  deliverablesText + '\n\n' +
  'PROPOSED TIMELINE\n' +
  (addendum.proposedTimeline || '') + '\n\n' +
  'COMMERCIAL NOTE\n' +
  (addendum.commercialNote || '') + '\n\n' +
  'NEXT STEPS\n' +
  (addendum.nextSteps || '') + '\n\n' +
  'Reference transcript: ' + projectData.transcriptUrl;

return [{
  json: {
    addendumTitle: addendum.addendumTitle || 'Expansion Addendum',
    executiveSummary: addendum.executiveSummary || '',
    expansionScope: addendum.expansionScope || '',
    additionalDeliverables: addendum.additionalDeliverables || [],
    proposedTimeline: addendum.proposedTimeline || '',
    commercialNote: addendum.commercialNote || '',
    nextSteps: addendum.nextSteps || '',
    docContent,
    projectId: projectData.projectId,
    projectName: projectData.projectName,
    existingNotes: projectData.existingNotes,
    companyId: projectData.companyId,
    companyName: projectData.companyName,
    dealId: projectData.dealId,
    meetingDate: projectData.meetingDate,
    transcriptUrl: projectData.transcriptUrl,
    slackChannelId: projectData.slackChannelId,
    contactName: projectData.contactName
  }
}];

